<?php
use EIPSI\ExternalApi as A;
function b_wait($path){$deadline=microtime(true)+20;while(!file_exists($path)){if(microtime(true)>$deadline)throw new RuntimeException('API2B barrier timeout');usleep(10000);}}
function b_spawn($input){$dir='/tmp/eipsi-api2b-'.bin2hex(random_bytes(8));mkdir($dir,0700);$pipes=array();$p=proc_open(array(PHP_BINARY,__DIR__.'/worker.php',$dir),array(0=>array('pipe','r'),1=>array('file',$dir.'/stdout','w'),2=>array('file',$dir.'/stderr','w')),$pipes);d2_assert(is_resource($p));fwrite($pipes[0],json_encode($input));fclose($pipes[0]);b_wait($dir.'/attempt');return array('process'=>$p,'dir'=>$dir);}
function b_join(&$job){b_wait($job['dir'].'/result.json');$r=json_decode(file_get_contents($job['dir'].'/result.json'),true);d2_assert(proc_close($job['process'])===0);$job['process']=null;return$r;}
function b_remove($job){if(!$job)return;if(is_resource($job['process'])){proc_terminate($job['process'],9);proc_close($job['process']);}foreach(glob($job['dir'].'/*')as$f)unlink($f);rmdir($job['dir']);}
b_case('Concurrent duplicate worker cannot claim an already running export',function(){$k=d2_key();$r=b_create($k);$a=null;$b=null;try{$a=b_spawn(array('op'=>'work','export'=>$r['export_id'],'pause'=>'claimed'));b_wait($a['dir'].'/paused');$b=b_spawn(array('op'=>'work','export'=>$r['export_id']));$result=b_join($b);d2_assert($result['status']===429&&$result['code']==='eipsi_external_export_busy');touch($a['dir'].'/release');d2_assert(b_join($a)['status']===200);$r=b_ready($k,$r);d2_assert(count(b_data($k,$r)['items'])===2);}finally{b_remove($a);b_remove($b);}});
foreach(array('claimed','chunk_written','before_ready')as$point)b_case('SIGKILL recovery with atomic chunks at '.$point,function()use($point){$k=d2_key();$r=b_create($k);$api=new A\DatasetSnapshots();$storage=new A\ExportStorage();$s=new A\Store();$job=null;try{
 if($point==='before_ready')while(($raw=$storage->get($r['export_id']))['next_source']<$raw['source_count'])$api->work($r['export_id']);
 $job=b_spawn(array('op'=>'work','export'=>$r['export_id'],'pause'=>$point));b_wait($job['dir'].'/paused');proc_terminate($job['process'],9);proc_close($job['process']);$job['process']=null;
 $s->rows($s->prepare('UPDATE '.$s->table('exports').' SET lease_until=0 WHERE id=%s',$r['export_id']));$r=b_ready($k,$r);d2_assert(count(b_data($k,$r)['items'])===2);$manifest=$api->manifest($k['principal'],$r['export_id']);d2_assert(hash('sha256',b_content($k,$r))===$manifest['sha256']);
 }finally{b_remove($job);}});
b_case('Concurrent key revoke wins before waiting download authorization',function(){$k=d2_key();$r=b_ready($k,b_create($k));$s=new A\Store();$job=null;try{$s->transaction(function()use($s,$k,$r,&$job){$s->key($k['key']['id'],true);$job=b_spawn(array('op'=>'download','secret'=>$k['secret'],'export'=>$r['export_id']));usleep(100000);d2_assert(!file_exists($job['dir'].'/result.json'));$s->rows($s->prepare('UPDATE '.$s->table('keys').' SET revoked_at=%d,revision=revision+1 WHERE id=%s',time(),$k['key']['id']));});$result=b_join($job);d2_assert($result['status']===401);}finally{b_remove($job);}});
b_case('Privacy revoke after copy but before delivery suppresses all emitted bytes',function(){$p=d2_publish(true);$f=d2_finish($p);$k=d2_key(array($p['definition']['study']['logical_id']));$r=b_ready($k,b_create($k,$p));$job=null;try{$job=b_spawn(array('op'=>'download','secret'=>$k['secret'],'export'=>$r['export_id'],'pause'=>'download_copied'));b_wait($job['dir'].'/paused');d2_withdraw($f['frame'],'DO_NOT_USE');touch($job['dir'].'/release');$result=b_join($job);d2_assert($result['status']===410&&$result['code']==='eipsi_external_snapshot_invalidated'&&!isset($result['data']));}finally{b_remove($job);}});
b_case('Source manifest excludes responses committed during later capture batches',function(){$p=d2_publish();for($i=0;$i<12;$i++)d2_finish($p,'BEFORE_'.$i);$k=d2_key(array($p['definition']['study']['logical_id']));$job=null;try{$job=b_spawn(array('op'=>'create','secret'=>$k['secret'],'code'=>$p['public'],'pause'=>'source_captured'));b_wait($job['dir'].'/paused');d2_finish($p,'DURING_CAPTURE');touch($job['dir'].'/release');$result=b_join($job);d2_assert($result['status']===200);$r=b_ready($k,$result['data']);d2_assert(count(b_data($k,$r)['items'])===12&&strpos(json_encode(b_data($k,$r)['items']),'DURING_CAPTURE')===false);d2_assert(count(d2_read($k,array(),$p)['items'])===13);}finally{b_remove($job);}});
